#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int n;
    if (scanf("%d", &n) != 1) return 0;

    long long *h = (long long *)malloc(sizeof(long long) * n);
    long long *leftMax = (long long *)malloc(sizeof(long long) * n);

    for (int i = 0; i < n; i++) {
        scanf("%lld", &h[i]);
    }

    long long cur = 0;
    for (int i = 0; i < n; i++) {
        if (h[i] > cur) cur = h[i];
        leftMax[i] = cur;
    }

    long long rightMax = 0;
    int count = 0;

    for (int i = n - 1; i >= 0; i--) {
        if (h[i] > rightMax) rightMax = h[i];

        long long level = leftMax[i] < rightMax ? leftMax[i] : rightMax;
        if (level - h[i] >= 1) {
            count++;
        }
    }

    printf("%d\n", count);

    free(h);
    free(leftMax);

    return 0;
}
